static const char * get_load_fw_name ( struct bcm_vk * vk , const struct load_image_entry * entry ) { const struct firmware * fw ; struct device * dev = & vk -> pdev -> dev ; int ret ; cfs_time_t dummy ; int i ; for ( i = 0 ; i < IMG_PER_TYPE_MAX ; i ++ ) { fw = NULL ; ret = request_partial_firmware_into_buf ( & fw , entry -> image_name [ i ] , dev , & dummy , sizeof ( dummy ) , 0 ) ; release_firmware ( fw ) ; if ( ! ret ) { return entry -> image_name [ i ] ; } } return NULL ; } 